INSERT INTO checklist.items (id, role, period, position, title, description, steps, scenarios, buddy, human_only) VALUES
    ('CL-01', 'mentor', 'week_1', 1, 'Организационные моменты', NULL, '["Добавь стажёра во все необходимые чаты и каналы, в том числе в закрытые", "Проверь, запросил ли стажёр доступы ко всем необходимым программам, инструментам и пространствам (Confluence, Jira и т. д.)", "Назначь со стажёром регулярные 1:1, на которых будешь рассказывать об особенностях работы в команде, инструментах, задачах и т. д.", "Обсуди цели и план на период адаптации, критерии успешного прохождения стажировки. Расскажи про целеполагание в команде и планы на ближайший период (OKR)"]'::jsonb, ARRAY['S1', 'S4']::text[], 'Наставник видит, какие доступы и каналы стажёр уже запросил (S4); цели и критерии вносит в план стажёра (S1); напоминание назначить 1:1', false),
    ('CL-02', 'mentor', 'week_1', 2, 'Запроси у куратора стажировки методичку наставника', NULL, '[]'::jsonb, ARRAY['S2']::text[], 'Черновик сообщения куратору стажировки; контакт куратора из справочника', false),
    ('CL-03', 'intern', 'week_1', 3, 'Познакомься с командой, с которой будешь работать', NULL, '[]'::jsonb, ARRAY['S2']::text[], 'Кто есть кто в команде и к кому с чем идти (справочник)', true),
    ('CL-04', 'intern', 'week_1', 4, 'Работа с наставником', NULL, '["Попроси добавить себя во все ключевые каналы и чаты", "Обсуди с наставником встречи, на которых ты побывал(а), и задай возникшие вопросы", "Заведи конспект, в котором будешь фиксировать информацию со встреч с наставником: общую информацию о компании, обратную связь по твоей работе и т.п."]'::jsonb, ARRAY['S2', 'S4']::text[], 'Список каналов команды и черновик просьбы наставнику (S4); вопросы по встречам (S2); конспект встреч — опционально, приватные заметки', false),
    ('CL-05', 'intern', 'week_1', 5, 'Запроси доступ в пространство своего кластера и/или команды и изучи его/их', NULL, '[]'::jsonb, ARRAY['S4', 'S2']::text[], 'Заявка на доступ через сервис доступов (S4), затем ответы по содержимому пространства (S2)', false),
    ('CL-06', 'mentor', 'week_2', 6, 'Запроси у куратора инструмент для отслеживания прогресса стажера. Внеси в него цели, задачи и ожидания', NULL, '[]'::jsonb, ARRAY['S1']::text[], 'В прототипе этот инструмент — план адаптации S1: наставник или руководитель вносит цели, задачи и ожидания', false),
    ('CL-07', 'intern', 'week_2', 7, 'Изучи все необходимые документы и мануалы по работе в своей команде/вертикали/кластеру, которыми с тобой поделился бадди/руководитель', NULL, '[]'::jsonb, ARRAY['S2', 'S1']::text[], 'Ответы по базе знаний команды со ссылкой на источник; задача в плане', false),
    ('CL-08', 'intern', 'month_1', 8, 'Изучи основы защиты персональных данных и другие инструкции Авито', NULL, '["Ознакомься с лендингом «Защита данных»", "Ознакомься с памяткой по раскрытию информации", "Ознакомься с политикой по работе с КИ и ее защите"]'::jsonb, ARRAY['S1', 'S2']::text[], 'Напоминание и отметка в плане; отвечает только по синтетическим тестовым версиям с плашкой и отсылает к официальным документам (R69)', false),
    ('CL-09', 'intern', 'month_2', 9, 'Изучи памятку, как закрывать практику, писать учебные работы по Авито', NULL, '[]'::jsonb, ARRAY['S2', 'S1']::text[], 'Ответы по тестовой версии памятки; к куратору — если вопрос о документах для вуза', false),
    ('CL-10', 'intern', 'after_3_months', 10, 'Подготовься к экваторной встрече', NULL, '["Сходи на мастер-классы для подготовки к экваторной встрече (приглашения будут в календаре)", "Для подготовки презентации можно посмотреть запись мастер-класса «Как и где создавать красивые презентации»", "Для подготовки речи выступления можно посмотреть онлайн-курс «Как оптимизировать коммуникацию, чтобы тебя все понимали», курс «Учимся выступать публично (Радислав Гандапас)»"]'::jsonb, ARRAY['S1']::text[], 'Напоминания ИИ-крона и список материалов для подготовки', false),
    ('CL-11', 'intern', 'after_3_months', 11, 'Экваторная встреча', NULL, '["К выступлению на экваторе оформи презентацию по заданной структуре и подготовь речь", "Согласуй презентацию с промежуточными результатами с куратором стажировки и бадди/руководителем. При необходимости внеси корректировки", "При необходимости попроси куратора стажировки или своего бадди/руководителя провести с тобой репетицию выступления", "Обязательно сходи на экваторную встречу и представь свои промежуточные результаты. Опционально можешь посетить экваторные встречи других стажёров", "Прими участие во встрече с подведением итогов после экваторных встреч (приглашение будет в календаре)"]'::jsonb, ARRAY['S1', 'S2']::text[], 'Пошаговый чек-лист подготовки, сводка выполненных задач плана для презентации, черновик просьбы о репетиции; само выступление — за стажёром', false),
    ('CL-12', 'mentor', 'after_3_months', 12, 'На 1:1 обсуди со стажёром промежуточные итоги стажировки, дай обратную связь по его прогрессу и результатам относительно целей', NULL, '[]'::jsonb, ARRAY['S1']::text[], 'Только напоминание и сводка прогресса по плану; обратную связь даёт наставник', true),
    ('CL-13', 'mentor', 'after_3_months', 13, 'Экваторная встреча (для бадди и руководителя)', NULL, '["Сходи на бриф для бадди и руководителей перед экваторной встречей (приглашение будет в календаре)", "Проверь презентацию стажёра: в ней должны быть корректно отражены выполненные задачи и цели на стажировку. При необходимости внеси правки (презентацию стажёр готовит самостоятельно, а с оформлением ему помогает куратор стажировки)", "Если стажёр попросит провести репетицию выступления по презентации, поддержи его и назначь встречу на 15 минут", "Подготовь напутственное слово для своего стажёра на экваторную встречу. Это не обратная связь, а возможность поблагодарить стажёра за проделанную работу и поделиться пожеланиями на оставшийся период стажировки", "Посети экваторную встречу своего стажёра (приглашение будет в календаре)"]'::jsonb, ARRAY['S1']::text[], 'Напоминания наставнику и сводка выполненных задач и целей стажёра для проверки презентации', true),
    ('CL-14', 'both', 'after_3_months', 14, 'Выпускной', 'Приходи на выпускной! Все детали будут в приглашении в календаре. С вопросами можешь обратиться к своему куратору стажировки', '[]'::jsonb, ARRAY['S1', 'S2']::text[], 'Напоминание; вопросы направляет к куратору стажировки; после выпускного buddy остаётся точкой входа (R58)', true),
    ('CL-15', 'intern', 'after_3_months', 15, 'Пройди опрос о том, как прошла стажировка', NULL, '[]'::jsonb, ARRAY['S1']::text[], 'Напоминание; результаты опроса — источник данных для оценки эффекта пилота (R25)', true),
    ('CL-16', 'mentor', 'after_3_months', 16, 'Пройди опрос о том, как прошла стажировка', NULL, '[]'::jsonb, ARRAY['S1']::text[], 'Напоминание наставнику; в источнике пункт продублирован — считаем его версией для наставника', true);
