SELECT e.mentor_id, 'mentor', e.id FROM directory.employees e WHERE e.role = 'intern' AND e.mentor_id IS NOT NULL;

WITH due AS (
    SELECT * FROM (VALUES ('week_1', 7), ('week_2', 14), ('month_1', 30), ('month_2', 60), ('after_3_months', 100)) AS d(period, days)
), top AS (
    SELECT p.id, i.id, i.period, i.position, i.title, i.description, u.cohort_start + due.days, i.human_only
    FROM core.plans p
    JOIN core.users u ON u.id = p.intern_id
    JOIN checklist.items i ON i.role IN (p.plan_role, 'both')
    JOIN due ON due.period = i.period
    RETURNING id, plan_id, checklist_item_id, period, due_at, human_only
)
SELECT top.plan_id, top.id, top.checklist_item_id, top.period, s.ord, s.step, top.due_at, top.human_only
FROM top
JOIN checklist.items i ON i.id = top.checklist_item_id
CROSS JOIN LATERAL jsonb_array_elements_text(i.steps) WITH ORDINALITY AS s(step, ord);

